local ECSComponent = import("Frame.ECS.ECSComponent")
---@class CookingComponent
local CookingComponent = Class("CookingComponent", ECSComponent)

function CookingComponent:__init()
    ECSComponent.__init(self)
    self._allUnlockRecipeData = {}       --所有获得的食谱
    self._curUseFoodId = 0               --当前使用食物的id
    self._collectData = {}               --收藏的信息
    self._allActivateData = {}                 --手动解锁的信息

    self._isActiveBattleFood = 0         --是否使用战斗料理开关
    self.EventOnAppQuit = Events.AddListener(Constants.EventNames.ONAPPQUIT, Bind(self, self.OnAppQuit))

    self._redPointMap = {}               --小红点的数据
end

function CookingComponent:__delete()
    self._allUnlockRecipeData = nil
    self._curUseFoodId = nil            
    self._collectData = nil              
    self._allActivateData = nil                --手动解锁的信息

    self._isActiveBattleFood = nil       
    self._redPointMap = {}               --小红点的数据
end

--
function CookingComponent:Initial(jsonData, unlockData)
    self._allUnlockRecipeData = {}
    self._collectData = {}
    self._allActivateData = {}

    for k, v in pairs(jsonData) do
        self._allUnlockRecipeData[checkString(v)] = 1
    end
    local t = CfUtils.GetLocalData("COOKINGCOLLECT")
    if checkString(t) == "0" then
    else
        self._collectData = checkTable(table.deserialize(t))
    end

    for k, v in pairs(unlockData) do
        self._allActivateData[checkString(v)] = 1
    end
end

---OnAppQuit 游戏结束时写入本地数据
function CookingComponent:OnAppQuit()
    CfUtils.WriteLocalData("COOKINGCOLLECT", table.serialize(self._collectData))
    Events.RemoveListener(Constants.EventNames.ONAPPQUIT, self.EventOnAppQuit)
end

--使用了的料理信息
function CookingComponent:InitialBattleCookingData(jsonData)   
    self._curUseFoodId = checkNumber(jsonData)
end

--使用开关
function CookingComponent:InitialActiveBattleFood(jsonData)
    self._isActiveBattleFood = checkNumber(jsonData)
end

--料理入口
function CookingComponent:CookingHomeReq(cb)
    GameUtils.Request(Interfaces.CookingHome, {}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        if cb then
            cb()
        end
    end)
end

--设置战斗料理加成开关
function CookingComponent:CookingBattleCookingSwitchReq(isOpen, cb)
    GameUtils.Request(Interfaces.CookingBattleCookingSwitch, {isOpen = isOpen}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        self._isActiveBattleFood = checkNumber(isOpen)

        if cb then
            cb()
        end
    end)
end

--设置当前使用的料理
function CookingComponent:CookingSetBattleFoodReq(foodId, cb)
    local CookingUtils = import('Game.UI.Phone.Cooking.CookingUtils')
    local vo = CookingUtils.GetBattleCookingFoodVo(foodId)
    if not vo then
        return
    end
    GameUtils.Request(Interfaces.CookingSetBattleBuff, {id = foodId}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data

        local lastUseFoodId = self._curUseFoodId
        --只能有一个
        self._curUseFoodId = checkNumber(foodId)
        
        if cb then
            cb(lastUseFoodId)
        end
    end)
end

--设置当前使用的料理
function CookingComponent:CookingBuyBattleCookingReq(foodId, num, cb)
    local CookingUtils = import('Game.UI.Phone.Cooking.CookingUtils')
    local vo = CookingUtils.GetBattleCookingFoodVo(foodId)
    if not vo then
        return
    elseif GoodsUtils.GetThingNo(vo.goodsConsum) < checkNumber(vo.goodsConsumNum) * num then
        GameUtils.Toast(localize("货币不足"))
        return
    end
    GameUtils.Request(Interfaces.CookingBuyBattleCooking, {id = foodId, num = num}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        GoodsUtils.DrawRewards({
            { goodsId = vo.goodsConsum, num = checkNumber(vo.goodsConsumNum) * num * -1}
        })
        GoodsUtils.DrawRewards(jsonData.rewards) 
        if cb then
            cb()
        end
    end)
end

--收藏一个食物
function CookingComponent:CollectFood(id)
    if checkNumber(id) == 0 then
        return
    end
    self._collectData[checkString(id)] = 1

    CfUtils.WriteLocalData("COOKINGCOLLECT", table.serialize(self._collectData))
end

--取消收藏一个食物
function CookingComponent:UnCollectFood(id)
    if checkNumber(id) == 0 then
        return
    end
    self._collectData[checkString(id)] = nil

    CfUtils.WriteLocalData("COOKINGCOLLECT", table.serialize(self._collectData))
end

--是否收藏了食物
function CookingComponent:IsCollectFood(id)
    return (checkNumber(self._collectData[checkString(id)]) == 1)
end

--获得一个食谱
function CookingComponent:AddRecipe(id)
    if checkNumber(id) <= 0 then
        return
    end
    
    if checkNumber(self._allUnlockRecipeData[checkString(id)] == 0) then
        self._redPointMap[checkString(id)] = 1
    end
    self._allUnlockRecipeData[checkString(id)] = 1
end

--扣除使用料理的生效次数
function CookingComponent:DelUseBattleFoodTime(questId)
    if checkNumber(self._curUseFoodId) == 0 then
        return 
    end
    local CookingUtils = import('Game.UI.Phone.Cooking.CookingUtils')
    local isBlack = CookingUtils.IsBlankQuestByQuestId(questId)
    if isBlack then
        return
    end

    --测试关卡不消耗
    local type = GoodsUtils.GetIdType(questId, Constants.IDArea.Quests)
    if type == Constants.IDType.QuestTrainField then
        return
    end

    GoodsUtils.DrawRewards({
        {
            goodsId = self._curUseFoodId,
            num = -1
        }
    })

    local num = GoodsUtils.GetThingNo(self._curUseFoodId)
    if num <= 0 then
        self._curUseFoodId = 0
    end
end

--是否有食谱
function CookingComponent:IsHaveRecipe(id)
    if checkNumber(id) <= 0 then
        return false
    end

    return checkNumber(self._allUnlockRecipeData[checkString(id)]) == 1
end

--是否使用了该料理
function CookingComponent:IsUseBattleFood(id)
    if checkNumber(self._curUseFoodId) == 0 then
        return false
    end
    return checkNumber(id) == checkNumber(self._curUseFoodId)
end

--是否激活了食物
function CookingComponent:IsHasActivateFood(id)
    if checkNumber(id) <= 0 then
        return false
    end

    return checkNumber(self._allActivateData[checkString(id)]) == 1
end

--是否使用了该料理
function CookingComponent:ActivateFoodReq(id, cb)
    if checkNumber(id) == 0 then
        return false
    end
    GameUtils.Request(Interfaces.cookingUnlockFavorabilityCooking, {id = id}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        self._allActivateData[checkString(id)] = 1

        if cb then
            cb()
        end
    end)
end

--获取当前使用的食物
function CookingComponent:GetCurUseFoodId()
    return checkNumber(self._curUseFoodId)
end

--删除一份小红点数据
function CookingComponent:RemoveRedPointMapById(recipeId)
    recipeId = checkNumber(recipeId)
    if recipeId <= 0 then
        return
    end
    self._redPointMap[checkString(recipeId)] = nil
end

function CookingComponent:IsNewRecipe(recipeId)
    recipeId = checkNumber(recipeId)
    if recipeId <= 0 then
        return false
    end
    return checkNumber(self._redPointMap[checkString(recipeId)]) == 1
end

function CookingComponent:IsActiveBattleFood()
    return (checkNumber(self._isActiveBattleFood) == 1)
end

function CookingComponent:SetActiveBattleFood(isTrue)
    self._isActiveBattleFood = (isTrue and 1 or 0)
end

return CookingComponent